using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Same validated own-profile identity as pets: server + character name, not
// the session actor. Capture callbacks only publish identity; all file IO and
// configuration changes stay on the existing UI timer / settings-save path.
internal sealed class HotbarProfiles {
 internal sealed class Entry {public string Name;public int Server;public SkillSlotsOptions Options;}
 internal sealed class Store {public int Version=1;public string Last;public SkillSlotsOptions Template;public Dictionary<string,Entry> Profiles=new Dictionary<string,Entry>();}
 sealed class Identity {internal string Name,Flow;internal int Server;internal double Time;}
 readonly object gate=new object();readonly string path;readonly bool preview;Store store;Identity incoming;long inputRevision,seenRevision;string selected,serialized,error;double latest=-1,lastTick=-100;bool live,dirty,blocked;internal long Revision;
 internal HotbarProfiles(string root,SkillSlotsOptions initial,bool preview){path=Path.Combine(root,"hotbar-profiles.json");this.preview=preview;store=new Store{Template=Local(initial)};if(preview)return;
  try{if(!File.Exists(path))return;if(new FileInfo(path).Length>1024*1024)throw new InvalidDataException("Hotbar profile file is too large.");var read=NativeHudFile.Json().Deserialize<Store>(File.ReadAllText(path));if(read==null||read.Version!=1||read.Profiles==null||read.Profiles.Count>64||read.Template==null)throw new InvalidDataException("Unsupported hotbar profile file.");read.Template.Normalize();foreach(var pair in read.Profiles){var p=pair.Value;if(p==null||!Valid(p.Name,p.Server)||pair.Key!=Key(p.Name,p.Server)||p.Options==null)throw new InvalidDataException("Invalid hotbar character profile.");p.Options.Normalize();p.Options=Local(p.Options);}if(read.Last!=null&&!read.Profiles.ContainsKey(read.Last))throw new InvalidDataException("Unknown saved hotbar character.");store=read;selected=read.Last;serialized=selected==null?null:Text(store.Profiles[selected].Options);
  }catch(Exception ex){if(!Expected(ex))throw;blocked=true;error="Could not load hotbar profiles. The existing file was preserved.";}
 }
 static bool Expected(Exception e){return e is IOException||e is InvalidDataException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException;}
 static bool Valid(string name,int server){return !string.IsNullOrWhiteSpace(name)&&name.Length<=64&&!name.Any(char.IsControl)&&server>=1000&&server<3000;}
 static string Key(string name,int server){return server+"/"+name;}
 static string Text(SkillSlotsOptions o){return NativeHudFile.Json().Serialize(Local(o));}
 // HUD-export selection and retained legacy preferences are global: never
 // switch them with a character layout or restore them from a character preset.
 static SkillSlotsOptions Local(SkillSlotsOptions o){var copy=o.Copy();copy.HideNativeHotbar=null;copy.NativeHotbarPath="";copy.PreparedHudFile="";return copy;}
 static SkillSlotsOptions Merge(SkillSlotsOptions saved,SkillSlotsOptions current){var next=saved.Copy();next.HideNativeHotbar=current.HideNativeHotbar;next.NativeHotbarPath=current.NativeHotbarPath;next.PreparedHudFile=current.PreparedHudFile;return next;}
 internal SkillSlotsOptions Startup(SkillSlotsOptions current){return selected!=null?Merge(store.Profiles[selected].Options,current):current;}
 internal void Consume(byte[] b,int s,int e,double time,string flow){if(b==null||s<0||e>b.Length||e-s<2||string.IsNullOrEmpty(flow)||double.IsNaN(time)||double.IsInfinity(time))return;int op=b[s]*256+b[s+1];if(op!=0x3336&&op!=0x1536)return;string name=null;int server=0;uint actor=0;if(op==0x3336){if(!PetSignal.Identity(b,s,e,out name,out server,out actor)||!Valid(name,server)){byte role;if(!DpsSignal.PlayerIdentity(b,s,e,true,out actor,out name,out role))return;name=null;server=0;}}lock(gate){if(time<latest)return;if(op==0x1536){if(incoming==null||incoming.Flow!=flow)return;incoming=null;}else incoming=new Identity{Name=name,Server=server,Flow=flow,Time=time};latest=time;inputRevision++;}}
 internal void Reset(){lock(gate){incoming=null;latest=-1;inputRevision++;}}
 internal SkillSlotsOptions Sync(SkillSlotsOptions current){Identity identity;lock(gate){if(seenRevision==inputRevision)return null;seenRevision=inputRevision;identity=incoming;}live=identity!=null&&identity.Name!=null;Revision++;if(identity==null||blocked)return null;if(identity.Name==null){if(selected==null)return null;Remember(current);selected=null;serialized=null;var fallback=Local(store.Template);fallback.KnownSlots.Clear();return Merge(fallback,current);}string nextKey=Key(identity.Name,identity.Server);if(selected==nextKey)return null;
  Remember(current);Entry next;if(!store.Profiles.TryGetValue(nextKey,out next)){if(store.Profiles.Count>=64){error="Hotbar profile limit reached. Existing profiles were preserved.";live=false;return null;}var options=Local(store.Template);if(store.Profiles.Count>0){options.Placements.Clear();options.KnownSlots.Clear();}next=new Entry{Name=identity.Name,Server=identity.Server,Options=options};store.Profiles[nextKey]=next;}
  selected=store.Last=nextKey;serialized=Text(next.Options);dirty=true;Flush();return Merge(next.Options,current);
 }
 internal void Remember(SkillSlotsOptions current){if(blocked)return;var local=Local(current);string text=Text(local);if(selected==null){if(Text(store.Template)==text)return;store.Template=local;}else{if(serialized==text)return;store.Profiles[selected].Options=local;serialized=text;}dirty=true;}
 internal void Tick(double now,SkillSlotsOptions current){if(now-lastTick<2)return;lastTick=now;Remember(current);Flush();}
 internal void Save(SkillSlotsOptions current){Remember(current);Flush();}
 void Flush(){if(!dirty||preview||blocked)return;try{VisualTweaks.NoLinks(path);NativeHotbar.Atomic(path,Encoding.UTF8.GetBytes(NativeHudFile.Json().Serialize(store)));dirty=false;error=null;}catch(Exception ex){if(!Expected(ex))throw;error="Could not save hotbar profiles. Previous saved data was preserved.";}Revision++;}
 internal string Name {get{return selected==null?null:store.Profiles[selected].Name;}}
 internal int Server {get{return selected==null?0:store.Profiles[selected].Server;}}
 internal string State {get{return error??(selected==null?"No character detected. Enter the game with the Helper open.":live?"Changes are saved automatically for this character.":"Saved character profile · waiting for login.");}}
 internal object Diagnostic {get{return new{character=Name,server=selected==null?(int?)null:Server,live,profiles=store.Profiles.Count,state=State,error};}}
 internal static void Verify(string root){string folder=Path.Combine(root,"profile-cases");Directory.CreateDirectory(folder);var initial=new SkillSlotsOptions{Enabled=true,Scale=70,HideNativeHotbar=true,NativeHotbarPath="native-file",PreparedHudFile="global-hud.dat"};initial.KnownSlots.Add(new SkillSlotAssignment{Index=23,Skill=15060000});initial.Ensure(23,0).Key="Q";var profiles=new HotbarProfiles(folder,initial,false);if(profiles.Name!=null)throw new Exception("Never invent an initial character");profiles.Save(initial);var a=EnemyTargetVerification.Player(12,"HotbarA",100,200,true);profiles.Consume(a,0,a.Length,1,"A");var first=profiles.Sync(initial);if(first==null||first.Placements[0].Key!="Q"||first.Scale!=70||first.HideNativeHotbar!=true||first.PreparedHudFile!="global-hud.dat")throw new Exception("First confirmed character preserves legacy layout and global native preference");first.Scale=90;first.Placements[0].Visible=false;profiles.Save(first);
  var b=EnemyTargetVerification.Player(34,"HotbarB",100,200,true);profiles.Consume(b,0,b.Length,2,"B");var second=profiles.Sync(first);if(second==null||second.Placements.Count!=0||second.KnownSlots.Count!=0||second.Scale!=70||second.HideNativeHotbar!=true||second.PreparedHudFile!="global-hud.dat")throw new Exception("A new character cannot inherit another character's keys, hidden slots or assignments");second.Scale=130;second.Ensure(7,0).Key="T";profiles.Save(second);profiles.Consume(a,0,a.Length,3,"new-A-flow");var returned=profiles.Sync(second);if(returned==null||returned.Scale!=90||returned.Placements[0].Visible||returned.Placements[0].Key!="Q")throw new Exception("Reconnect restores the correct character independent of actor/flow");profiles.Save(returned);
  var restarted=new HotbarProfiles(folder,initial,false);var startup=restarted.Startup(initial);if(restarted.Name!="HotbarA"||startup.Scale!=90||!restarted.State.StartsWith("Saved character"))throw new Exception("Restart restores saved profile without claiming a live character");var sameNameOtherServer=(byte[])a.Clone();int pos=2;uint id;DpsSignal.Var(sameNameOtherServer,ref pos,sameNameOtherServer.Length,out id);int end=pos+6+Encoding.UTF8.GetByteCount("HotbarA");sameNameOtherServer[end]=0x16;sameNameOtherServer[end+1]=5;restarted.Consume(sameNameOtherServer,0,sameNameOtherServer.Length,4,"other-server");var other=restarted.Sync(startup);if(other==null||restarted.Server!=1302||other.Placements.Count!=0)throw new Exception("Same name on another server must use an independent profile");restarted.Reset();restarted.Sync(other);if(!restarted.State.StartsWith("Saved character"))throw new Exception("Reset revokes live authority but keeps saved settings");
  var unknown=(byte[])a.Clone();unknown[end]=0;unknown[end+1]=0;restarted.Consume(unknown,0,unknown.Length,5,"unknown-server");var unbound=restarted.Sync(other);if(restarted.Name!=null||unbound==null||unbound.KnownSlots.Count!=0)throw new Exception("An unsupported identity cannot keep editing the former character");restarted.Save(unbound);restarted.Consume(a,0,a.Length,6,"A-again");var recovered=restarted.Sync(unbound);if(recovered==null||recovered.Scale!=90||recovered.Placements[0].Key!="Q")throw new Exception("Unknown identity cannot overwrite saved character settings");
  var history=new ConfigurationHistory();var c=new EnergyConfiguration{Options=new EnergyBarOptions(),SkillSlots=first.Copy()};history.Observe(c);c=c.Copy();c.Maximum=999;history.Observe(c);history.RebaseHotbar(second);EnergyConfiguration undone;if(!history.Undo(out undone)||undone.SkillSlots.Scale!=130||undone.Maximum==999)throw new Exception("Undo after character switch must retain current hotbar and other-module history");
  string target=Path.Combine(folder,"hotbar-profiles.json");var saved=File.ReadAllBytes(target);if(File.ReadAllText(target).Contains("global-hud.dat"))throw new Exception("Export-copy paths are global, not stored in individual character profiles");File.WriteAllText(target,"{\"Version\":99}");var damaged=new HotbarProfiles(folder,initial,false);damaged.Save(initial);if(File.ReadAllText(target)!="{\"Version\":99}")throw new Exception("Invalid store must not be overwritten");File.WriteAllBytes(target,saved);
 }
}
